import React from 'react';
import { 
  List, 
  ListItem, 
  ListItemButton,
  ListItemIcon, 
  ListItemText, 
  Switch, 
  Paper,
  Typography,
  Box
} from '@mui/material';
import PaletteIcon from '@mui/icons-material/Palette';
import DarkModeIcon from '@mui/icons-material/DarkMode';
import { useAppTheme } from '@app/theme';
import { useTranslation } from '@fanfanlo';

export function ThemeSettingsSection() {
  const { t } = useTranslation('homepage/components/page/settings/content/content');
  const { mode, setMode, toggleColorMode } = useAppTheme();

  return (
    <Box sx={{ mt: 2, mb: 1 }}>
      <Typography variant="subtitle2" color="text.secondary" sx={{ px: 2, mb: 1 }}>
        {t('ThemeSettingsSection.label.appearance')}
      </Typography>
      <Paper elevation={0} variant="outlined" sx={{ borderRadius: 2, overflow: 'hidden' }}>
        <List disablePadding>
          <ListItem 
            divider
            secondaryAction={
              <Switch 
                edge="end" 
                checked={mode === 'dark'} 
                onChange={toggleColorMode}
                data-testid="ThemeSettingsSection__darkModeSwitch__01JK2WVZA1I8H5Y"
                data-test-comment="深色模式开关，开启后应用深色皮肤"
              />
            }
          >
            <ListItemIcon>
              <DarkModeIcon />
            </ListItemIcon>
            <ListItemText 
              primary={t('ThemeSettingsSection.darkMode.primary')}
              secondary={mode === 'dark' ? t('ThemeSettingsSection.darkMode.opened') : t('ThemeSettingsSection.darkMode.closed')} 
            />
          </ListItem>
          
          <ListItem 
            disablePadding
            secondaryAction={
               <Switch 
                edge="end" 
                checked={mode === 'system'} 
                onChange={(e) => setMode(e.target.checked ? 'system' : 'light')} 
                data-testid="ThemeSettingsSection__systemModeSwitch__01JK2WVZA2J9I6Z"
                data-test-comment="跟随系统开关，开启后根据操作系统偏好自动切换主题"
              />
            }
          >
            <ListItemButton 
                onClick={() => setMode(mode === 'system' ? 'light' : 'system')}
                data-testid="ThemeSettingsSection__systemModeBtn__01JK2WVZA3K0J7A"
                data-test-comment="跟随系统列表项按钮，点击可切换跟随状态"
            >
              <ListItemIcon>
                <PaletteIcon />
              </ListItemIcon>
              <ListItemText 
                primary={t('ThemeSettingsSection.followSystem.primary')}
                secondary={mode === 'system' ? t('ThemeSettingsSection.followSystem.opened') : t('ThemeSettingsSection.followSystem.closed')} 
              />
            </ListItemButton>
          </ListItem>
        </List>
      </Paper>
    </Box>
  );
}
